P = [1, 2, 3, 5, 4]
def bubble(a, early_exit):
    a = a[:]; comps = swaps = 0; log = []; n = len(a)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            comps += 1; log.append((a[j], a[j+1]))
            if a[j] > a[j+1]:
                a[j], a[j+1] = a[j+1], a[j]; swaps += 1; swapped = True
        if early_exit and not swapped: break
    return a, comps, swaps, log
def insertion(a):
    a = a[:]; comps = swaps = 0; log = []
    for i in range(1, len(a)):
        j = i
        while j > 0:
            comps += 1; log.append((a[j-1], a[j]))      # element comparison only
            if a[j-1] > a[j]:
                a[j-1], a[j] = a[j], a[j-1]; swaps += 1; j -= 1
            else: break
    return a, comps, swaps, log
for ee in (False, True):
